import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Density relative to best available, times room for the best second pick after taking this item."""
    k = values.shape[0]
    if k <= 1:
        return np.zeros(k)
    w = np.maximum(weights, 1)
    dens = values / w
    best = dens.max()
    if best <= 0:
        return np.zeros(k)
    thr = remaining - weights  # >= 0 since every candidate fits
    # second_i = max dens_j over j != i with w_j <= thr_i
    # exact broadcast over k <= 200
    fits = weights[None, :] <= thr[:, None]  # (k, k): j fits after picking i
    np.fill_diagonal(fits, False)            # self-exclusion
    masked = np.where(fits, dens[None, :], -np.inf)
    second = masked.max(axis=1)
    second = np.where(np.isfinite(second), second, 0.0)
    return (dens / best) * (0.5 + 0.5 * second / best)

